package main

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestSecurityFixes(t *testing.T) {
	srv := NewServer(NewApp("files", "admin-secret"))

	// 1. Path traversal into ../secret/signing.key must fail
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/files?name=docs/../../secret/signing.key", nil)
	req.Header.Set("Authorization", "Bearer tok-alice")
	srv.ServeHTTP(rec, req)
	if rec.Code == 200 {
		t.Fatalf("path traversal succeeded: %s", rec.Body.String())
	}
	t.Logf("traversal attempt -> %d %s", rec.Code, rec.Body.String())

	// 2. Legit file still readable
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("GET", "/files?name=docs/readme.txt", nil)
	req.Header.Set("Authorization", "Bearer tok-alice")
	srv.ServeHTTP(rec, req)
	t.Logf("legit file -> %d %s", rec.Code, rec.Body.String())

	// 3. Mass assignment: bob tries to become admin via PUT /me
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("PUT", "/me", strings.NewReader(`{"name":"Bob","email":"bob@example.test","role":"admin"}`))
	req.Header.Set("Authorization", "Bearer tok-bob")
	srv.ServeHTTP(rec, req)
	t.Logf("PUT /me -> %d %s", rec.Code, rec.Body.String())
	if strings.Contains(rec.Body.String(), `"role":"admin"`) {
		t.Fatalf("privilege escalation succeeded")
	}

	// 4. IDOR: bob tries to read alice's private note (id=1)
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("GET", "/notes/1", nil)
	req.Header.Set("Authorization", "Bearer tok-bob")
	srv.ServeHTTP(rec, req)
	t.Logf("bob GET /notes/1 -> %d %s", rec.Code, rec.Body.String())
	if rec.Code == 200 {
		t.Fatalf("IDOR: bob read alice's note")
	}

	// 5. Unauthenticated delete of alice's note must fail
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("DELETE", "/notes/1", nil)
	srv.ServeHTTP(rec, req)
	t.Logf("anon DELETE /notes/1 -> %d %s", rec.Code, rec.Body.String())
	if rec.Code == 204 {
		t.Fatalf("unauthenticated delete succeeded")
	}

	// 6. Bob deleting alice's note must fail
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("DELETE", "/notes/1", nil)
	req.Header.Set("Authorization", "Bearer tok-bob")
	srv.ServeHTTP(rec, req)
	t.Logf("bob DELETE /notes/1 -> %d %s", rec.Code, rec.Body.String())
	if rec.Code == 204 {
		t.Fatalf("bob deleted alice's note")
	}
}
EOF
cp /tmp/claude/manual_check_test.go ./zz_manual_security_test.go
go test ./... -run TestSecurityFixes -v
rm ./zz_manual_security_test.go

